import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 한 번에 내려받을 수 있는 최대 행 수
const MAX_ROWS = 50000;
// 가정: 다운로드는 웹에서만 요청되므로 접속 로그의 로그인 구분은 '웹'
const LOGIN_TYPE = '웹';

interface ScreenDef {
  columns: [string, string][];
  select: string;
  from: string;
  dateCond: string;
  order: string;
}

// 가정: 다운로드 대상 화면 구분 값은 아래 4가지 (입력에 허용 값 없음)
const SCREENS: Record<string, ScreenDef> = {
  ATTENDANCE_DAILY: {
    columns: [['employeeName', '사원'], ['workDate', '근무일자'], ['clockInAt', '출근시각'], ['clockOutAt', '퇴근시각'], ['sourceType', '기록 출처'], ['closingStatus', '마감 상태']],
    select: 't.attendance_daily_id AS "attendanceDailyId", e.name AS "employeeName", CAST(t.work_date AS text) AS "workDate", CAST(t.clock_in_at AS text) AS "clockInAt", CAST(t.clock_out_at AS text) AS "clockOutAt", t.source_type AS "sourceType", t.closing_status AS "closingStatus"',
    from: 'attendance_daily t LEFT JOIN employee e ON e.employee_id = t.employee_id',
    dateCond: '(CAST(:startDate AS date) IS NULL OR t.work_date >= CAST(:startDate AS date)) AND (CAST(:endDate AS date) IS NULL OR t.work_date <= CAST(:endDate AS date))',
    order: 't.work_date, t.attendance_daily_id',
  },
  ATTENDANCE_REQUEST: {
    columns: [['employeeName', '신청자'], ['typeName', '근태항목'], ['startDate', '시작일'], ['endDate', '종료일'], ['reason', '사유'], ['approvalStatus', '결재 진행 상태']],
    select: 't.attendance_request_id AS "attendanceRequestId", e.name AS "employeeName", ty.type_name AS "typeName", CAST(t.start_date AS text) AS "startDate", CAST(t.end_date AS text) AS "endDate", t.reason AS "reason", t.approval_status AS "approvalStatus"',
    from: 'attendance_request t LEFT JOIN employee e ON e.employee_id = t.employee_id LEFT JOIN attendance_type ty ON ty.attendance_type_id = t.attendance_type_id',
    dateCond: '(CAST(:startDate AS date) IS NULL OR t.end_date >= CAST(:startDate AS date)) AND (CAST(:endDate AS date) IS NULL OR t.start_date <= CAST(:endDate AS date))',
    order: 't.start_date, t.attendance_request_id',
  },
  ANNUAL_LEAVE: {
    columns: [['employeeName', '임직원'], ['leaveYear', '대상 연도'], ['grantedDays', '생성 일수'], ['adjustedDays', '조정 일수'], ['usedDays', '사용 일수'], ['confirmStatus', '확정 여부']],
    select: 't.annual_leave_id AS "annualLeaveId", e.name AS "employeeName", t.leave_year AS "leaveYear", t.granted_days AS "grantedDays", t.adjusted_days AS "adjustedDays", t.used_days AS "usedDays", t.confirm_status AS "confirmStatus"',
    from: 'annual_leave t LEFT JOIN employee e ON e.employee_id = t.employee_id',
    dateCond: '(CAST(:startDate AS date) IS NULL OR t.leave_year >= EXTRACT(YEAR FROM CAST(:startDate AS date))) AND (CAST(:endDate AS date) IS NULL OR t.leave_year <= EXTRACT(YEAR FROM CAST(:endDate AS date)))',
    order: 't.leave_year, t.annual_leave_id',
  },
  ACCESS_LOG: {
    columns: [['employeeName', '임직원'], ['eventType', '이벤트 구분'], ['accessedAt', '접속·사용 일시'], ['loginType', '로그인 구분'], ['targetInfoType', '열람 대상 정보 유형']],
    select: 't.access_log_id AS "accessLogId", e.name AS "employeeName", t.event_type AS "eventType", CAST(t.accessed_at AS text) AS "accessedAt", t.login_type AS "loginType", t.target_info_type AS "targetInfoType"',
    from: 'access_log t LEFT JOIN employee e ON e.employee_id = t.employee_id',
    dateCond: '(CAST(:startDate AS date) IS NULL OR CAST(t.accessed_at AS date) >= CAST(:startDate AS date)) AND (CAST(:endDate AS date) IS NULL OR CAST(t.accessed_at AS date) <= CAST(:endDate AS date))',
    order: 't.accessed_at, t.access_log_id',
  },
};

// 조회 범위(전체·부서·개인) 안의 행만 (가정: 사용자의 사용 중인 메뉴 권한 중 가장 넓은 범위, 없으면 개인)
const SCOPE_COND = "(CAST(:scope AS text) = '전체' OR (CAST(:scope AS text) = '개인' AND t.employee_id = CAST(:userId AS bigint)) OR (CAST(:scope AS text) = '부서' AND e.department_id = (SELECT department_id FROM employee WHERE employee_id = CAST(:userId AS bigint))))";
const FILTER_COND = '(CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint)) AND (CAST(:employeeId AS bigint) IS NULL OR t.employee_id = CAST(:employeeId AS bigint))';

function optText(v: unknown): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  return String(v);
}

function optDate(v: unknown): string | null {
  const s = optText(v);
  if (s !== null && !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '날짜는 YYYY-MM-DD 형식으로 입력하세요.');
  }
  return s;
}

function optId(v: unknown, label: string): string | null {
  const s = optText(v);
  if (s !== null && !/^[0-9]+$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return s;
}

function esc(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function cell(v: unknown): string {
  const text = v === null || v === undefined ? '' : String(v);
  return '<Cell><Data ss:Type="String">' + esc(text) + '</Data></Cell>';
}

function buildExcel(def: ScreenDef, rows: Record<string, unknown>[]): string {
  const lines: string[] = [];
  lines.push('<Row>' + def.columns.map((c) => cell(c[1])).join('') + '</Row>');
  for (const row of rows) {
    lines.push('<Row>' + def.columns.map((c) => cell(row[c[0]])).join('') + '</Row>');
  }
  const xml = '<?xml version="1.0" encoding="UTF-8"?>'
    + '<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">'
    + '<Worksheet ss:Name="조회결과"><Table>'
    + lines.join('')
    + '</Table></Worksheet></Workbook>';
  return Buffer.from(xml, 'utf8').toString('base64');
}

@Controller('api/v1')
export class FnSfr01808Controller {
  @Get('/excel-downloads')
  async downloadQueryResultExcel(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자', '자원 담당자', '시스템 관리자');
    const query = checks.queryOf(req.query);
    const targetScreen = optText(query['targetScreen']);
    if (targetScreen === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '다운로드 대상 화면을 선택하세요.');
    }
    const startDate = optDate(query['startDate']);
    const endDate = optDate(query['endDate']);
    const departmentId = optId(query['departmentId'], '부서');
    const employeeId = optId(query['employeeId'], '사원');
    if (startDate !== null && endDate !== null && startDate > endDate) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일은 종료일보다 늦을 수 없습니다.');
    }
    if (!Object.prototype.hasOwnProperty.call(SCREENS, targetScreen)) {
      throw new ApiError(422, 'INVALID_TARGET_SCREEN', '지원하지 않는 다운로드 대상 화면입니다.');
    }
    const def = SCREENS[targetScreen];
    const ip = String(req.ip ?? '0.0.0.0').slice(0, 45);

    return transaction(async (db) => {
      const scopes = await db.query(
        "SELECT view_scope AS \"viewScope\" FROM menu_permission WHERE employee_id = CAST(:userId AS bigint) AND use_yn = '사용'",
        { userId: user.id },
      );
      const found = (scopes as Record<string, unknown>[]).map((r) => r['viewScope']);
      const scope = found.includes('전체') ? '전체' : found.includes('부서') ? '부서' : '개인';

      const sql = 'SELECT ' + def.select
        + ' FROM ' + def.from
        + ' WHERE ' + SCOPE_COND + ' AND ' + FILTER_COND + ' AND ' + def.dateCond
        + ' ORDER BY ' + def.order
        + ' LIMIT ' + MAX_ROWS;
      const rows = (await db.query(sql, {
        scope,
        userId: user.id,
        startDate,
        endDate,
        departmentId,
        employeeId,
      })) as Record<string, unknown>[];

      if (rows.length === 0) {
        throw new ApiError(404, 'NO_DATA_TO_DOWNLOAD', '다운로드할 조회 결과가 없습니다.');
      }

      let file: string;
      try {
        file = buildExcel(def, rows);
      } catch (e) {
        throw new ApiError(502, 'EXCEL_GENERATION_FAILED', '엑셀 파일 생성에 실패했습니다. 잠시 후 다시 시도하세요.');
      }

      // 개인정보가 포함될 수 있는 조회 결과 다운로드는 접속·사용 로그로 기록
      await db.execute(
        "INSERT INTO access_log (employee_id, menu_id, event_type, accessed_at, login_ip, login_type, second_auth_result, target_info_type, created_at, updated_at) VALUES (CAST(:userId AS bigint), NULL, '개인정보열람', now(), :ip, :loginType, NULL, :targetInfoType, now(), now())",
        { userId: user.id, ip, loginType: LOGIN_TYPE, targetInfoType: targetScreen },
      );

      return { file };
    });
  }
}

