import { useState } from 'react';
import { Band, DataTable, DateInput, DateText, Drawer, Field, Form, LookupSelect, Select, Tiles, call } from '../kit';
import type { PageProps, Row } from '../kit';

// 가정: 다운로드 대상 화면 구분 값
const SCREENS: [string, string][] = [
  ['ATTENDANCE_DAILY', '일별 근태'],
  ['ATTENDANCE_REQUEST', '근태 신청'],
  ['ANNUAL_LEAVE', '연차'],
  ['ACCESS_LOG', '접속·사용 로그'],
];

function screenName(code: unknown): string {
  const found = SCREENS.find((s) => s[0] === code);
  return found ? found[1] : String(code ?? '');
}

function saveFile(base64: string, fileName: string) {
  const bin = atob(base64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) {
    bytes[i] = bin.charCodeAt(i);
  }
  const blob = new Blob([bytes], { type: 'application/vnd.ms-excel' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  a.click();
  URL.revokeObjectURL(url);
}

export default function FnSfr01808Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [targetScreen, setTargetScreen] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [history, setHistory] = useState<Row[]>([]);

  const close = () => {
    setOpen(false);
  };

  const submit = async () => {
    if (!targetScreen) {
      throw new Error('다운로드 대상 화면을 선택하세요.');
    }
    if (startDate && endDate && startDate > endDate) {
      throw new Error('조회 시작일은 종료일보다 늦을 수 없습니다.');
    }
    const result = await call<{ file: string }>('GET', '/excel-downloads', role, undefined, {
      targetScreen,
      startDate,
      endDate,
      departmentId,
      employeeId,
    });
    saveFile(result.file, targetScreen + '.xls');
    setHistory([
      {
        id: history.length + 1,
        targetScreen,
        startDate,
        endDate,
        departmentId,
        employeeId,
        downloadedAt: new Date().toISOString(),
      },
      ...history,
    ]);
    notify('엑셀 파일을 내려받았습니다.');
    close();
  };

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>이번 접속 다운로드</h2>
        <Tiles items={[['다운로드 건수', history.length]]} />
      </section>
      <section className="box span-8">
        <h2>엑셀 다운로드</h2>
        <Band>
          <button type="button" onClick={() => setOpen(true)}>엑셀 다운로드</button>
        </Band>
      </section>
      <section className="box span-12">
        <h2>다운로드 내역</h2>
        <DataTable
          rows={history}
          empty="다운로드한 내역이 없습니다."
          columns={[
            { key: 'targetScreen', label: '다운로드 대상 화면', render: (r) => screenName(r['targetScreen']) },
            { key: 'startDate', label: '조회 시작일', render: (r) => <DateText value={r['startDate']} /> },
            { key: 'endDate', label: '조회 종료일', render: (r) => <DateText value={r['endDate']} /> },
            { key: 'employeeId', label: '사원', render: (r) => (r['employeeId'] ? <RefEmployee role={role} value={r['employeeId']} /> : '전체') },
            { key: 'downloadedAt', label: '다운로드 일시', render: (r) => <DateText value={r['downloadedAt']} time /> },
          ]}
        />
      </section>
      {open && (
        <Drawer title="엑셀 다운로드" onClose={close}>
          <Form onSubmit={submit} submit="다운로드">
            <Field label="다운로드 대상 화면 구분" required>
              <Select value={targetScreen} onChange={setTargetScreen} options={SCREENS} />
            </Field>
            <Field label="조회 시작일">
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
            <Field label="조회 종료일">
              <DateInput value={endDate} onChange={setEndDate} />
            </Field>
            <Field label="부서">
              <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} />
            </Field>
            <Field label="사원">
              <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}

function RefEmployee({ role, value }: { role: string; value: unknown }) {
  return <RefNameShim role={role} value={value} />;
}

import { RefName } from '../kit';

function RefNameShim({ role, value }: { role: string; value: unknown }) {
  return <RefName table="employee" role={role} value={value} />;
}
